style.css:
@-moz-document domain("espn.com"), domain("espn.co.uk"), domain("espn.com.au"), domain("espn.in"), domain("espn.nl"), domain("espn.com.br"), domain("espn.com.mx"), domain("espn.com.ar"), domain("espn.cl"), domain("espn.co.cr"), domain("espn.com.co"), domain("espn.com.ve"), domain("espn.com.sg"), domain("espn.ph"), domain("espn.com.pe"), domain("espn.com.ec"), domain("espn.com.uy"), domain("espn.com.gt"), domain("espn.com.pa"), domain("espn.com.do") {
:root { color-scheme: dark !important; }

  /* ---- Base surfaces ---- */
  html, body { background-color: #14181d !important; color: #c4cdd6 !important; }
  #global-viewport, #main-container, #content, .main-content, .page-container,
  .layout, [class*="layout-"], .contentFeed, .one-feed-wrapper, .container,
  .col-a, .col-b, .col-c, .col-one, .col-two, .col-three, .col-main {
    background-color: transparent !important; }
  .main-content, #global-scoreboard, .scoreboard-content { background-color: #14181d !important; }

  /* ---- Soften all default light borders ---- */
  * { border-color: #262c33 !important; }

  /* ---- Header / global nav ---- */
  #global-header, #custom-nav, .Nav, .Site--nav, header[role="banner"] { background-color: #0d1117 !important; }
  #global-nav, .Nav__Primary, .Nav__Secondary, #global-nav-secondary,
  .global-nav-container, .navigation { background-color: #0d1117 !important; }
  #global-header { border-bottom: 2px solid #c8102e !important; } /* ESPN red accent */
  /* .Nav__Primary__Menu is the top-level nav <ul>, NOT a dropdown — painting it
     the elevated panel colour striped the header into two tones (#1c2128 behind
     the link groups, #0d1117 in the gaps). The real flyout is .Nav__Dropdown. */
  .Nav__Dropdown, .Nav__Dropdown__Menu, .dropdown-menu,
  .Flyout, .Flyout__Inner { background-color: #1c2128 !important; }
  .Nav__Primary__Menu { background-color: transparent !important; }
  .Nav a, .nav__link, #global-nav a, .Nav__Primary__Menu__Link,
  .Nav__Secondary__Menu__Link, .global-nav a { color: #e6edf3 !important; }
  .Nav a:hover, #global-nav a:hover, .Nav__Primary__Menu__Link:hover { color: #ffffff !important; }
  .nav-menu, .menu-flyout, .QuickMenu, .HeaderUserMenu, .HeaderUserMenu__Menu { background-color: #1c2128 !important; }

  /* ---- Scoreboard strip / score chips ---- */
  #global-scoreboard, .HeaderScoreboard, .HeaderScoreboard__Wrapper,
  .scores-carousel, .scoreboards, .scoreboard { background-color: transparent !important; }
  .cscore, .cscore_item, .cscore_link, .scoreboard, .gameStrip, .game-strip,
  .Scoreboard, .ScoreCell, .ScoreboardScoreCell {
    background-color: #1c2128 !important; border-color: #2d333b !important; }
  .cscore_name, .cscore_score, .ScoreCell__Score, .ScoreCell__TeamName,
  .gameStrip__competitors, .ScoreboardScoreCell__Item,
  .scoreEvent__athlete, .scoreEvent__score, .scoreEvent__position,
  .scoreEvent__description, .scoreEvent__competitors, .cscore_rank,
  .cscore_aggregate, .scoreCell__Score, .gameStrip__team-name { color: #e6edf3 !important; }
  .cscore_date-time, .cscore_date, .cscore_network, .cscore_info, .cscore_info-overview,
  .cscore_notes, .cscore_status, .cscore_odds, .scoreEvent__status,
  .ScoreCell__Time, .Schedule__Time, .scoreEvent__event, .scoreEvent__title { color: #8b949e !important; }
  /* Non-live scoreboard-strip clock/status ("AET", "FT", a kickoff time) and the
     two-legged-tie note ("Vuelta / Agr. 2-2") are plain neutral labels natively
     (#000 / #48494a), but they sit inside the chip's <a>, so the `a span` rule painted
     them link-blue — status text rendered as a hyperlink, right beside the grey
     .cscore_status metadata on the same chip. The live clock rule below is more
     specific and keeps its red. Two-class selectors are required: `a span` is (0,1,1),
     so a one-class rule loses the !important tie. */
  .cscore_time, .cscore_time.time,
  .cscore_link .cscore_aggregate-title,
  .cscore_link .cscore_aggregate-details,
  .cscore_link .cscore_aggregate-score,
  .cscore_link .cscore_notes_game { color: #c4cdd6 !important; }
  /* Legacy scoreboard-strip clock: ESPN paints an in-progress game's time RED
     (#dd0000, e.g. "5:56 - 4th") to flag LIVE games apart from scheduled/final;
     the generic grey + link-blue rules flatten it so a live game reads identical to
     a scheduled one. Scope to .cscore--live so ONLY in-progress clocks go red. */
  .cscore--live .cscore_time, .cscore--live .cscore_time.time,
  .cscore--live .cscore_status {
    color: #ff5a5a !important; -webkit-text-fill-color: #ff5a5a !important; }
  /* Same live/not-live signal one component over: a one-feed scoreEvent (golf/tennis
     leaderboards, "Rd 4 - In Progress") paints .scoreEvent__status ESPN live-red
     #dd0000 while a scheduled/final event leaves it grey. The generic grey rule above
     lists .scoreEvent__status, flattening BOTH into the same grey — a live tournament
     then reads exactly like a concluded one. Re-red only the live state. */
  .scoreEvent--live .scoreEvent__status {
    color: #ff5a5a !important; -webkit-text-fill-color: #ff5a5a !important; }
  /* Legacy video-duration chips paint a translucent WHITE pill with dark #1d1e1f
     text; a bare white label turned them white-on-white. Re-tone the pill dark,
     matching the next-gen .Media__Duration treatment further down. */
  .media-duration, .video-length {
    background-color: rgba(13,17,23,0.78) !important; color: #ffffff !important; }
  .timestamp--overlay { color: #ffffff !important; }

  /* ---- Score-section labels / headers (default light bg) ---- */
  #pane-main, .scoreLabel_content, .scoreLabel, #favfeed-footer {
    background-color: #14181d !important; }
  .scoreLabel_title, .ContentList__Header, .Card__Header,
  .section-header, .mod-header, h2[class*="Label"] {
    background-color: transparent !important; color: #e6edf3 !important; }
  #favfeed-footer a { color: #8ab4d8 !important; }

  /* ---- Betting widgets (default very-light bg) ---- */
  .betting, [class*="betting"], .bettingLabel, .bettingPrimary, .bettingSecondary,
  .bettingTeamSeparator, .Betting, .ProviderLogo, .pick-center-data {
    background-color: #181d23 !important; }
  .betting *, [class*="betting"] * { color: #c4cdd6 !important; }

  /* ---- DTC / ESPN+ upsell tiles (default white) ---- */
  .dtc-upsell, [class*="dtc-upsell"], .Espnplus, .WatchTile, .WatchTile__Content,
  .upsell, .premiumUpsell { background-color: #1a1f26 !important; border-color: #2d333b !important; }
  .dtc-upsell__cta__btn, .WatchTile__Button {
    background-color: #c8102e !important; color: #ffffff !important; border-color: #c8102e !important; }

  /* ---- Content cards / feed items ---- */
  .contentItem, .contentItem--collection, .contentItem--featured,
  .contentItem--game-strip, .contentItem--headlineStack, article.contentItem,
  .contentCollection, .contentCollection--hero, .headlineStack, .headlineStack--top-headlines,
  .sub-module, .sub-module.editorial, article.sub-module, .module, .module.sideLogin,
  .sideLogin, .Card, .card, .scoreCollection, .scoreEvent, .scoreEvent__content,
  .MiniCard, .miniCard, .now-feed-item, .news-feed-item, .QuickLinks,
  .contentItem__padding--border, .mod-container, .mod-content {
    background-color: #1c2128 !important; border-color: #2d333b !important; }
  .contentItem--featured, .contentCollection--hero { background-color: #1a1f26 !important; }
  .contentItem:hover, .scoreEvent__content:hover, .cscore_link:hover,
  .news-feed-item:hover { background-color: #21262d !important; }
  /* Quick-Links rail rows ("Watch on ESPN", "Quick Links", the 404 link columns) hardcode
     a solid #fff on :hover — not token-driven, and a hover state so invisible to a
     load-time scan. Match the card hover surface. */
  .QuickLinks__Item:hover { background-color: #21262d !important; }

  /* ---- Typography ---- */
  h1, h2, h3, h4, h5, h6, .contentItem__subhead, .Card__Header__Title,
  .QuickLinks__Item__Title, .headline, .Story__Headline { color: #e6edf3 !important; }
  p, li, span, dd, dt, td, th, label, figcaption, time, small, b, strong, em,
  .contentItem__subhead, .news-feed-item p, .photoCaption, .sub-module .content p,
  .cscore_truncate { color: #c4cdd6 !important; }

  /* ---- Links: ESPN headline blue is too dark on dark → readable blue ---- */
  a, a span { color: #5fb0e6 !important; }
  a:hover { color: #9bd4ff !important; }
  /* A bold lead-in inside a link ("<b>Kram:</b> Grades for every trade") is part of the
     link, but the generic b/strong body-text rule above out-specifies `a` and greyed just
     that run — every ESPN inline link list rendered two-tone. Inherit the anchor's colour
     so headline-white and link-blue anchors both stay one colour. */
  a b, a strong { color: inherit !important; }
  /* headline links inside cards: bright, high-contrast */
  .contentItem__title, .contentItem__title--story, .contentItem__title--hero,
  .contentItem__title a, .headlineStack__list > li > a,
  .contentItem--headlineStack__list > li > a, .news-feed-item h1 a,
  .QuickLinks__Item__Title a, .AnchorLink {
    color: #e6edf3 !important; }
  .contentItem__title a:hover, .headlineStack__list > li > a:hover,
  .AnchorLink:hover { color: #5fb0e6 !important; }

  /* ---- Story / article body ---- */
  .article, #article-feed .article, .article-body, .Story, .Story__Body,
  .story-container, .article-header, .ContentList, .Article {
    background-color: transparent !important; color: #c4cdd6 !important; }
  .article-body p, .Story__Body p, .article-body li, .article p { color: #c4cdd6 !important; }
  .article-meta, .byline, .timestamp, .author, .article-timestamp, .Byline { color: #8b949e !important; }
  /* Next-gen recap/gamecast byline: the "Updated: <date>" meta hardcodes #6c6d6f
     (dark-grey) via .Byline__Meta--publishDate → ~3.1:1 dark-on-dark on the card. The
     .Byline rule above only colors the section; the child meta overrides it. Lift it. */
  .Byline__Meta, .Byline__Meta--publishDate, .Byline__TimestampWrapper { color: #9aa4ae !important; }
  /* When .author is an ANCHOR (one-feed shortstop cards link the name to the
     contributor page) the blanket metadata grey above swallowed ESPN's #3772df link
     colour, so the byline name became typographically identical to the timestamp
     beside it and lost every hint that it is clickable. A muted link blue restores the
     affordance without competing with the headline. Plain-span bylines stay grey. */
  a.author { color: #8ab4d8 !important; }
  /* Story pullquotes carry a 4px ESPN-red (#dd0000) left bar as a brand accent; the
     generic grey border-left flattened it to an invisible #2d333b strip on dark. Keep the
     panel dark but restore the brand-red bar (decorative, so the vivid ESPN red is fine). */
  blockquote, .article-body aside.inline, aside.inline {
    background-color: #1a1f26 !important; border-left: 4px solid #c8102e !important; color: #c4cdd6 !important; }
  figure, .article-figure { background-color: transparent !important; }
  .container-wrapper, .article-feed, .article-feed__container,
  .inline-content, .Story__feed { background-color: transparent !important; }
  /* reaction / share / icon buttons: dark glyph on dark → readable */
  .icon-button, .reactions-button, .reactions-button svg, .icon-button svg,
  .share-buttons button, .article-social .btn-social {
    color: #c4cdd6 !important; fill: #c4cdd6 !important; }
  .icon-button:hover, .reactions-button:hover { color: #e6edf3 !important; fill: #e6edf3 !important; }
  /* video play-button overlay: keep dark, not a bright leak */
  .Poster__Button, .media-wrapper__playbtn,
  .play-button, .VideoControls__PlayButton {
    background-color: rgba(20,24,29,0.7) !important; }
  /* .video-play-button is NOT the button — it is the full-size transparent overlay
     that SPANS the whole video thumbnail (300x169 / 149x84); the actual play control
     is its 32-64px ::before disc. Painting the overlay rgba(20,24,29,.7) laid a 70%
     dark scrim over every video thumbnail on the feed, so video cards rendered visibly
     washed-out beside ordinary photo cards. Native is transparent — keep it that way
     and let the white ::before disc read as the affordance it is (it sits on a photo). */
  .video-play-button { background-color: transparent !important; }

  /* ---- Tables (stats / standings) ---- */
  .Table, .Table2, table, .tablehead, .mpTable > table, .Table__TBODY,
  .Table2__table { background-color: transparent !important; }
  .Table__THEAD, .Table2__thead, thead, .Table__TH, .Table2__th, th,
  .tablehead tr.colhead, .Table__sub-header {
    background-color: #1c2128 !important; color: #e6edf3 !important; border-color: #2d333b !important; }
  .Table__TR, .Table2__tr, tr, td, .Table__TD, .Table2__td, .tablehead td {
    border-color: #2d333b !important; color: #c4cdd6 !important; }
  .Table__TR--sm, tr:nth-child(even), .Table__even { background-color: #181d23 !important; }
  .Table__TR:hover, tr:hover { background-color: #21262d !important; }
  /* Box-score / line-score DATA cells hardcode a solid white bg (baseball gamecast
     line score's PIT/WSH score rows) → light-grey numerals on white, unreadable.
     Audit-blind: each cell is <40px tall so it slips the light-surface size filter.
     Keep them transparent so the dark card + row striping show; the header row (TH)
     keeps its own dark band. ---- */
  .Table__TD, .Table2__td, td.playByPlay__linescore__score,
  /* A story-body <table class="inline-table"> puts its footnote row in a <tfoot> whose
     cell hardcodes a solid WHITE bg — an unclassed <td>, so neither the Table__TD rule
     nor the inline-white catch-all reaches it. Our already-pale footnote text then
     rendered white-on-white. */
  tfoot td { background-color: transparent !important; }

  /* ---- Forms / inputs / search ---- */
  input, textarea, select, .search-box, .Search__Input {
    background-color: #1c2128 !important; color: #e6edf3 !important; border-color: #2d333b !important; }
  input::placeholder { color: #8b949e !important; }
  /* Legacy global-search submit (.btn-search, desktop header AND the mobile in-nav search
     reveal) draws its magnifier as a BLACK raster PNG background-image — legible on ESPN's
     white field, ~1.4:1 once the input is dark, and no fill/color rule can touch a raster.
     Zero the button's own fill so the invert only flips the glyph, not a surface. */
  .btn-search { background-color: transparent !important; filter: invert(1) !important; }

  /* ---- Buttons ---- */
  .button, .btn, .Button, .button-alt, .button-filter, .btn-social,
  .pick-center-data .btn, .Nav__SignUp {
    background-color: #21262d !important; color: #e6edf3 !important; border-color: #2d333b !important; }
  .button:hover, .btn:hover, .Button:hover { background-color: #2d333b !important; }
  .button--primary, .Button--primary, .btn--alt, .Nav__SignUp--filled,
  .ContentList__Button {
    background-color: #c8102e !important; border-color: #c8102e !important; color: #ffffff !important; }
  .button--primary:hover, .Button--primary:hover { background-color: #e01b3c !important; }
  /* The neutral .button rule above swallows ESPN's filled brand CTAs, which are the
     ONLY thing separating a primary action from a dropdown pill. Restore them.
     .button--flagship WAS the ESPN+ subscribe CTA; the ESPN-on-Disney+ rebrand
     renamed it to .button--disneyPlus-watch (site: #3772df/white) and left our
     flagship rule matching nothing → the Subscribe conversion button shipped as an
     anonymous grey pill beside Create Account / Log In. Cover both class names; on
     dark we reuse ESPN's own [data-appearance="dark"] pairing (#588ae4 on near-black). */
  .button.button--flagship, .button.button--disneyPlus-watch {
    background-color: #588ae4 !important; border-color: #588ae4 !important;
    color: #121213 !important; -webkit-text-fill-color: #121213 !important; }
  .button.button--flagship:hover, .button.button--disneyPlus-watch:hover {
    background-color: #7aa1ea !important; }
  /* "Watch" CTA on the legacy scoreboard cards (.cscore_button on the home score strip,
     and the bare .button.sm variant in the one-feed game-strip card): ESPN fills it with
     the brand blue #3772df/white as the card's PRIMARY action, sitting beside the
     blue-OUTLINE Gamecast / Box Score secondaries. The neutral .button rule above
     swallowed the fill, so the primary read as a third grey pill and the whole
     action hierarchy collapsed. `.watch-link` alone is NOT a safe hook — the
     .cscore_header-link variant of the same class is a plain grey text link — so both
     classes are required. Same dark-on-blue pairing as the other filled CTAs. */
  .button.watch-link, .button.cscore_button {
    background-color: #588ae4 !important; border-color: #588ae4 !important;
    color: #121213 !important; -webkit-text-fill-color: #121213 !important; }
  .button.watch-link:hover, .button.cscore_button:hover {
    background-color: #7aa1ea !important; }
  /* Fantasy sign-up rail: already dark by design, with a per-sport brand fill on the
     first CTA and white-outline secondaries. We flattened all three to one grey pill. */
  .fantasySignupV2 .button {
    background-color: transparent !important; border-color: #ffffff !important;
    color: #ffffff !important; -webkit-text-fill-color: #ffffff !important; }
  .fantasySignupV2.fantasySignup-football .fantasySignup__cta .button:first-child {
    background-color: #2dcc30 !important; border-color: #2dcc30 !important;
    color: #101113 !important; -webkit-text-fill-color: #101113 !important; }
  .fantasySignupV2.fantasySignup-basketball .fantasySignup__cta .button:first-child {
    background-color: #ffaa00 !important; border-color: #ffaa00 !important;
    color: #101113 !important; -webkit-text-fill-color: #101113 !important; }
  .fantasySignupV2.fantasySignup-womens-basketball .fantasySignup__cta .button:first-child {
    background-color: #ff7700 !important; border-color: #ff7700 !important;
    color: #101113 !important; -webkit-text-fill-color: #101113 !important; }
  .fantasySignupV2.fantasySignup-hockey .fantasySignup__cta .button:first-child {
    background-color: #2eddf1 !important; border-color: #2eddf1 !important;
    color: #101113 !important; -webkit-text-fill-color: #101113 !important; }
  .fantasySignupV2.fantasySignup-baseball .fantasySignup__cta .button:first-child {
    background-color: #ff645f !important; border-color: #ff645f !important;
    color: #101113 !important; -webkit-text-fill-color: #101113 !important; }
  .fantasySignupV2 .fantasySignupEplus__cta .button {
    background-color: #fab200 !important; border-color: #fab200 !important;
    color: #101113 !important; -webkit-text-fill-color: #101113 !important; }
  /* Side-login / "Customise ESPN" account module: the site paints "Create Account"
     a FILLED brand-blue primary (.button) and "Log In" a blue-OUTLINE secondary
     (.button-alt). The neutral .button rules flattened both to identical grey pills,
     erasing the primary/secondary hierarchy. Restore the filled primary (reusing the
     dark-appropriate ESPN blue) and the outline secondary's blue accent. */
  .sideLogin .button, .module.sideLogin .button {
    background-color: #588ae4 !important; border-color: #588ae4 !important;
    color: #121213 !important; -webkit-text-fill-color: #121213 !important; }
  .sideLogin .button:hover, .module.sideLogin .button:hover {
    background-color: #7aa1ea !important; }
  /* .button-alt is ESPN's LEGACY blue-outline secondary (transparent fill, #3772df
     border + label) — the sideLogin "Log In" AND the game-strip card's
     Summary / Statistics / Commentary trio in the one-feed. The neutral .button rule
     above lists .button-alt itself, so every one of them shipped as a grey pill with
     no outline hierarchy. Same treatment as the prism .Button--alt below. */
  .button-alt, .sideLogin .button-alt, .module.sideLogin .button-alt {
    background-color: transparent !important; border-color: #588ae4 !important;
    color: #7aa9ee !important; -webkit-text-fill-color: #7aa9ee !important; }
  .button-alt:hover {
    background-color: #0d2450 !important; color: #9bd4ff !important;
    -webkit-text-fill-color: #9bd4ff !important; }
  /* Prism `.Button--*` modifier family (espnfitt). The neutral `.Button` rule above
     swallows ALL of it, so a primary, a secondary and a disabled control render as the
     same anonymous grey pill: .Button--default is the FILLED brand-blue primary
     (#3772df/white; ESPN's own dark pairing is #588ae4 on #121213), .Button--alt the
     blue-OUTLINE secondary — that is the "Gamecast" CTA on every scoreboard game card —
     .Button--eplus the ESPN+ gold, and .Button--disabled the greyed-out state. Note the
     class ESPN actually ships is `--default`, not the `--primary` the rules above name. */
  .Button.Button--default {
    background-color: #588ae4 !important; border-color: #588ae4 !important;
    color: #121213 !important; -webkit-text-fill-color: #121213 !important; }
  .Button.Button--default:hover { background-color: #7aa1ea !important; }
  .Button.Button--default .icon__svg { fill: #121213 !important; }
  .Button.Button--alt {
    background-color: transparent !important; border-color: #588ae4 !important;
    color: #7aa9ee !important; -webkit-text-fill-color: #7aa9ee !important; }
  .Button.Button--alt:hover {
    background-color: #0d2450 !important; color: #9bd4ff !important;
    -webkit-text-fill-color: #9bd4ff !important; }
  .Button.Button--alt .icon__svg { fill: #7aa9ee !important; }
  .Button.Button--eplus.Button--default {
    background-color: #fab200 !important; border-color: #fab200 !important;
    color: #121213 !important; -webkit-text-fill-color: #121213 !important; }
  .Button.Button--eplus.Button--alt {
    background-color: transparent !important; border-color: #fab200 !important;
    color: #fab200 !important; -webkit-text-fill-color: #fab200 !important; }
  .Button.Button--disabled {
    background-color: transparent !important; border-color: #4a525b !important;
    color: #6e7681 !important; -webkit-text-fill-color: #6e7681 !important; }
  /* Where-to-Watch row CTA + the scoreboard game-card "Watch" button: a filled brand-blue
     <a> whose only classes are hashed, so the `a` link rule painted its label #5fb0e6 on
     the site's own fill (~1.2:1). The data-testid is the one stable hook; reuse the
     theme's dark-on-blue CTA pairing. The fill MUST be pinned too — ESPN ships this same
     testid over two different blues (#5990f6 on Where-to-Watch, the darker #3772df on the
     scoreboard) and the dark label only clears 4.5:1 on the lighter one. */
  [data-testid="watchButton"] {
    background-color: #588ae4 !important; border-color: #588ae4 !important;
    color: #121213 !important; -webkit-text-fill-color: #121213 !important; }
  [data-testid="watchButton"]:hover { background-color: #7aa1ea !important; }
  /* Shot-map filter row (soccer match report / gamecast "SHOT MAP"): the shot-type pills
     and the All-Periods / All-Players dropdowns are built on `.Button--default`, so the
     filled brand-blue PRIMARY rule above turned the whole filter bank into a row of blue
     CTAs — and ESPN's selected pill (`--active`, #e0e0e0 against the #f9f9f9 unselected)
     collapsed into that same blue, so nothing showed which shot types were on. These are
     neutral controls, not primary actions: give them the theme's control surface and a
     lighter selected state. The pill glyph is a two-tone SVG resolving through
     --color-combo-white-gray90 / --color-combo-black-white, so it already darks correctly. */
  .ShotMapFilterButtons__Pill.Button--default,
  .ShotMapFilterButtons__Dropdown.Button--default {
    background-color: #21262d !important; border-color: #2d333b !important;
    color: #c4cdd6 !important; -webkit-text-fill-color: #c4cdd6 !important; }
  .ShotMapFilterButtons__Pill--active.Button--default {
    background-color: #2d333b !important; border-color: #4a525b !important;
    color: #e6edf3 !important; -webkit-text-fill-color: #e6edf3 !important; }

  /* ---- Tabs ---- */
  .tabs__list, .Tabs, .mod-tabs, .ui-tabs-nav, .ContentList__Tabs {
    background-color: transparent !important; border-color: #2d333b !important; }
  .tabs__list__item, .Tabs__Link, .ui-tabs-nav li a,
  .tabs__link, .tabs__list__item .Button--unstyled { color: #c4cdd6 !important; }
  .tabs__list__item--active, .Tabs__Link--active, .ui-tabs-selected a,
  .tabs__list__item--active .tabs__link,
  .tabs__list__item--active .Button--unstyled {
    color: #e6edf3 !important; border-bottom-color: #c8102e !important; }
  /* Segmented filter control (standings "League / Conference / Division"): ESPN paints
     the ACTIVE segment's label its live-red #dd0000 as the selected-state accent. The
     generic .AnchorLink white-headline rule flattened it, so all three segments read
     identical white (the pill outline still hints selection, but the brand accent — the
     theme's own active-tab convention — is lost). Restore a readable red on the active
     segment. */
  a.Button--filter.Button--active, .Button--filter.Button--active {
    color: #ff5a5a !important; -webkit-text-fill-color: #ff5a5a !important; }
  /* The active-segment red above matches the standings segmented control (ESPN paints
     it #dd0000), but the gamecast "Last Five Matches" team selector reuses the SAME
     .Button--filter.Button--active class while ESPN paints its active tab neutral
     near-black (#101113). The red bled onto the selected TEAM abbreviation, so an
     active "FRA" read as loss/negative red instead of "selected". Restore a neutral
     high-contrast label on the LastGames team name only. */
  button.Button--filter.Button--active .LastGames__TeamName,
  .Button--filter.Button--active .LastGames__TeamName {
    color: #e6edf3 !important; -webkit-text-fill-color: #e6edf3 !important; }

  /* ---- Promos / callouts / banners ---- */
  .promo, .scorePromo, .premiumEngagement, .callout, .alert, .notification-bar,
  .takeover, .promoModule, .EdpHeader, .ClubhouseHeader, .ClubhouseHeader.bg-clr-white {
    background-color: #1a1f26 !important; color: #c4cdd6 !important; border-color: #2d333b !important; }

  /* ---- Footer. NOT a bare `footer`: ESPN builds every card's action strip out of a
       <footer> too (.Card__Footer "All NBA News" / "Full Team Stats", the prism
       hashed-class variant, .contentItem__footer), all natively transparent. The page
       chrome colour then painted an inset near-black band inside each elevated card —
       a two-tone card the site never renders. The page footer always carries one of the
       classes below (or lives in .PageFooter__Footer). ---- */
  .PageFooter, .PageFooter__Footer, .PageFooter__QuickLinks, #global-footer,
  .footer, .Footer { background-color: #0d1117 !important; border-color: #2d333b !important; }
  .PageFooter a, .PageFooter__QuickLinks a, .Footer a { color: #8ab4d8 !important; }
  .PageFooter__Footer span, .PageFooter small, .copyright { color: #8b949e !important; }
  /* Legacy story pages append their own legal strip as an unclassed-by-our-rules
     <footer class="article-legal-footer">. The --bottom-fixed variant is a #f9f9fb bar
     pinned to the viewport bottom, held off-screen by translateY(100%) until a `.show`
     class slides it up mid-article — invisible to any load-time scan — and the --gray
     variant is the same fill inline in the article body. Its own `ul` ink is #1d1e1f. */
  .article-legal-footer--bottom-fixed, .article-legal-footer--gray {
    background-color: #14181d !important; border-color: #2d333b !important; }
  .article-legal-footer, .article-legal-footer ul { color: #8b949e !important; }

  /* ---- Ad surrounds: dark, no bright leaks (don't theme iframe content).
       Match "ad-" only at a CLASS-NAME BOUNDARY: a bare [class*="ad-"] also hits
       every contentItem__subhead--* (sub-h-e-"ad-"), painting a base-dark band
       behind story descriptions inside our elevated cards. ---- */
  .Ad, .ad, [class^="ad-"], [class*=" ad-"], [id^="ad-"], .advertisement, .Ad--banner,
  .Ad--inContent, .ad-banner-wrapper, .sponsoredHeadlines {
    background-color: #14181d !important; border-color: #262c33 !important; }
  .tbl-feed-header-text, .sponsoredHeadlines__title, .ad-feedback-text { color: #8b949e !important; }

  /* ---- Footer legal / OneTrust settings strip (default near-white) ---- */
  .PageFooter__Legal, .PageFooter__Legal__Copyright, .ot-sdk-show-settings,
  #onetrust-consent-sdk .ot-sdk-row, .legal { color: #8b949e !important; }
  /* ---- OneTrust / Disney consent SDK, shown on a first visit (the international editions
       raise it again on every fresh context). The banner and the "Show Purposes" preference
       centre are solid #fff panels the site never darkens: every heading, partner count and
       accordion label our generic text rules light up renders white-on-white, while ESPN's
       own near-black body copy stays black. Dark the two panels and lift the black copy;
       everything between them is transparent, except the footer, which paints its own #fff.
       .onetrust-pc-dark-filter is the scrim, not a surface — forcing it opaque would hide
       the panel it sits behind. ---- */
  #onetrust-banner-sdk, #onetrust-pc-sdk, #onetrust-pc-sdk .ot-pc-footer {
    background-color: #1c2128 !important; }
  #onetrust-policy-text, #onetrust-policy-text *, #ot-pc-desc, #ot-pc-desc *,
  #onetrust-pc-sdk .ot-acc-txt, #onetrust-pc-sdk .ot-accordion-layout button {
    color: #c4cdd6 !important; }
  #onetrust-pc-btn-handler {
    background-color: transparent !important; color: #e6edf3 !important;
    border-color: #8b949e !important; }
  /* The brand wordmark and the close control are black artwork on transparent, so no colour
     rule reaches either. The wordmark is a REPLACED-content image (`content: url(data:…)`)
     on the .ot-pc-logo box itself — its nested <img> is 0x0 and inverting that paints
     nothing. */
  #onetrust-pc-sdk .ot-pc-logo, #onetrust-banner-sdk .banner_logo,
  #onetrust-pc-sdk .ot-close-icon { filter: invert(1) !important; }
  /* The purpose-accordion chevron is a data-URI SVG background-image whose <path> declares
     no fill, so it paints pure black — 1.1:1 on the darked panel. The box behind it is
     transparent, so inverting the box only flips the glyph. */
  #onetrust-pc-sdk .ot-plus-minus { filter: invert(1) !important; }
  /* The banner's button-group rule is a `border-top` on a ::before, which the blanket `*`
     border reset cannot reach — a #dcdddf hairline the full width of the dark panel. */
  #onetrust-banner-sdk #onetrust-button-group-parent::before {
    border-top-color: #2d333b !important; }

  /* ---- Catch-all: any element ESPN paints white/near-white inline ---- */
  [style*="background-color: rgb(255, 255, 255)"],
  [style*="background:#fff"], [style*="background: #fff"],
  [style*="background-color:#fff"] { background-color: #1c2128 !important; }
  /* Dark text ESPN hardcodes (#1d1e1f / #48494a) → light, on our dark surfaces */
  [style*="color: rgb(29, 30, 31)"], [style*="color:#1d1e1f"],
  [style*="color: rgb(72, 73, 74)"], [style*="color:#48494a"] { color: #c4cdd6 !important; }

  /* ---- ESPN hardcoded GREY SCALE (clr-gray-01..09) — applied via CLASSES,
       not inline; drives stat numbers, leader values, box-score metadata,
       glossary, copyright. Remap the WHOLE scale: dark end → light for text. ---- */
  .clr-gray-01, .clr-gray-02 { color: #e6edf3 !important; } /* #151617 / darkest → primary text (numbers, names) */
  .clr-gray-03 { color: #c4cdd6 !important; }               /* #48494a → body */
  .clr-gray-04, .clr-gray-05 { color: #9aa4ae !important; } /* #6c6d6f → muted metadata (still ≥4.5 on cards) */
  /* ESPN semantic colour utilities: .clr-negative (#dd0000 — live match minute on the
     scoreboard, down movement, losses) and .clr-positive (green — up movement, wins)
     are a live/gain-loss signal. The .ScoreCell__Time grey rule + generic text rules
     flatten them to grey, so a live "71'" reads identical to a scheduled kickoff. Lift
     both to readable-on-dark equivalents so the signal survives. */
  .clr-negative { color: #ff5a5a !important; -webkit-text-fill-color: #ff5a5a !important; }
  .clr-positive { color: #4ac76a !important; -webkit-text-fill-color: #4ac76a !important; }
  /* .clr-brand-ESPN resolves to the same ESPN red as .clr-negative and marks an in-progress
     game ("LIVE!" in the team-page schedule rail). It is a single class, so it ties with the
     .Schedule__Time / .ScoreCell__Time metadata greys above and only wins by coming later —
     keep it below them. */
  .clr-brand-ESPN { color: #ff5a5a !important; -webkit-text-fill-color: #ff5a5a !important; }
  /* Module / section / panel titles ESPN colors with a dark grey (#2b2c2d) */
  .Stats__LeadersTitle, .Table__Title, .Card__Header__Title, .module-header,
  .headerCell__title, .pageHeader__title, .Wrapper__Header, .ContentList__Title,
  .Stats__Title, .StatBlock__Title, .TeamLeaders__Title, .clr-black, [class*="__Title"] {
    color: #e6edf3 !important; }
  /* Stat / leader / box-score containers that hardcode the same darks via class */
  .Athlete__Text--2xl-emph, .Athlete__Text--xl-emph, .Athlete__Text--lg-emph,
  .Athlete__PlayerName, .Athlete__Link, .Athlete h3, .Athlete h2,
  .StatBlock__Value, .StatBlockInner__Value, .Leaders__Item__Value,
  .TeamLeaders__Item, .player-leader-value, .fw-bold {
    color: #e6edf3 !important; }
  .Athlete__Text--md-emph, .Athlete__Stats, .Athlete__NameDetails,
  .StatBlock__Label, .Leaders__Item__Label, .glossary__title, .glossary__abbr {
    color: #c4cdd6 !important; }
  .Stats__footerText, .Stats__footerEmph, .Stats__TotalRow, .glossary__item,
  .LegalFooter__Copyright, .LegalFooter__Link, .ContentMetadata,
  .GameInfo__Meta, .Gamestrip__Time, .ScoreboardScoreCell__Note,
  /* box-score footnote ("+/- denotes…") hardcodes #6c6d6f → ~2.9:1 on the card */
  .TableDetails__Note { color: #9aa4ae !important; }
  /* Stat headers / sortable column links that color via class */
  .StatsTable__headerLink, .stats-cell, .Table__TH .AnchorLink,
  .Table__TH svg { color: #c4cdd6 !important; fill: #c4cdd6 !important; }
  /* Box-score line scores + column headings (1 2 3 4 T) → readable text */
  .ScoreboardScoreCell__Value, .ScoreboardScoreCell__Lines,
  .gameLineScore { color: #c4cdd6 !important; }
  .ScoreboardScoreCell__Heading { color: #9aa4ae !important; }
  /* Video duration pill: dark translucent over media, light text */
  .Media__Duration, .Media__Time {
    background-color: rgba(13,17,23,0.78) !important; color: #ffffff !important; }
  /* Scoreboard / game metadata hardcoding the same darks WITHOUT clr-gray-* */
  .ScoreboardScoreCell__Record, .LocationDetail__Item,
  .News__Item__Description, .News__Item__Timestamp,
  .GameInfo, .MatchInfo__Detail, .MatchInfo__Meta { color: #9aa4ae !important; }
  /* Game-info / match-info panels ESPN paints a light grey (#edeef0) */
  .MatchInfo, .GameInfo__Content, .Gamestrip, .competitors {
    background-color: #1c2128 !important; border-color: #2d333b !important; }
  .MatchInfo__Link, .MatchInfo a { color: #5fb0e6 !important; }
  /* "Back to Top" control is a <div> (not <a>) hardcoding link-blue #0066cc → low
     contrast on dark; lift to our readable blue. */
  .BackToTop, .BackToTop a { color: #5fb0e6 !important; }

  /* ---- "More Sports" mega-menu + per-sport top-nav flyouts (white) —
       .submenu-wrapper / ul.split, plus the bare inner <ul>/<li> the flyout panel
       is actually painted on (the wrapper is dark but its direct-child <ul> ships
       solid white; flyout is closed at load = audit-blind). ---- */
  .submenu-wrapper, ul.split, ul.split.three, .split.three, .submenu, .sub-nav-menu,
  .Nav__Secondary__Submenu, .Nav__Submenu, .nav-submenu, .navbar-submenu,
  .submenu-wrapper ul, .submenu-wrapper li, .submenu-wrapper .sub {
    background-color: #1c2128 !important; border-color: #2d333b !important; }
  .submenu-wrapper a, ul.split a, .submenu a, .Nav__Secondary__Submenu a,
  .submenu-wrapper a span { color: #e6edf3 !important; }
  .submenu-wrapper a:hover, ul.split a:hover, .submenu a:hover,
  .submenu-wrapper a:hover span { color: #9bd4ff !important; }
  /* flyout caret: a CSS-border triangle pointing at the nav item — recolor its
     bottom border (the fill) to the dark panel so it doesn't glare white. The
     caret is painted by the ACTIVE PARENT <li> (::before), not by the panel
     wrapper — audit-blind twice over (pseudo + only while a flyout is open). */
  .submenu-wrapper::before, .submenu-wrapper::after,
  .submenu-wrapper ul::before, .submenu-wrapper ul::after,
  .submenu-parent-active::before, .submenu-parent-active::after,
  #global-header li.user a::before, #global-header li.user a::after,
  #global-header li.search a::before, #global-header li.search a::after {
    border-bottom-color: #1c2128 !important; border-top-color: #1c2128 !important; }
  /* The SELECTED sport's caret is a different pseudo: li.active (no flyout involved), and
     it is filled with the SECONDARY bar's colour, not the flyout's — natively #fff against
     the white per-sport nav below, so it reads as a notch rather than a marker. Against
     our dark secondary bar the untouched white triangle is the loudest thing in the
     header. ESPN's own [data-appearance='dark'] half paints it #252627, i.e. matched to
     the dark bar; mirror that with our bar colour. Only rendered on a sport page. */
  #global-nav > ul > li.active::before,
  #global-nav > ul > li.submenu-parent-active::before {
    border-bottom-color: #0d1117 !important; }

  /* ---- Per-sport SECONDARY nav (#global-nav-secondary "Scores / Teams / Stats /
       Odds / More") dropdowns: the panel is a bare unclassed <div> holding a
       ul.single / ul.split, none of which the .submenu-wrapper rules above reach,
       so every one of them ships solid white. Closed at load = audit-blind. ---- */
  #global-nav-secondary li.has-sub > div,
  #global-nav-secondary li.has-sub > div div,
  #global-nav-secondary li.has-sub > div ul,
  #global-nav-secondary li.has-sub > div li,
  #global-nav-secondary li.has-sub > div a {
    background-color: #1c2128 !important; border-color: #2d333b !important; }
  #global-nav-secondary li.has-sub > div a,
  #global-nav-secondary li.has-sub > div a span { color: #e6edf3 !important; }
  #global-nav-secondary li.has-sub > div a:hover,
  #global-nav-secondary li.has-sub > div a:hover span {
    background-color: #21262d !important; color: #ffffff !important; }
  /* division / conference group headings inside the Teams mega-panel */
  #global-nav-secondary li.has-sub > div .label,
  #global-nav-secondary li.has-sub > div .conference { color: #9aa4ae !important; }

  /* ---- Header search autocomplete flyout (.search_results): opens over the nav
       as a solid white panel with dark section headers. Closed at load, so the
       element-bg scan never sees it. ---- */
  .search_results, .search_results--active, .search_results__wrapper,
  .search_results__autocomplete, .search_result__group, .search_results__group,
  .search_results__suggestions, .search_results__item {
    background-color: #1c2128 !important; border-color: #2d333b !important; }
  .search_results__header { color: #e6edf3 !important; }
  .search_results__cat { color: #9aa4ae !important; }
  .search_results__item:hover, .search_results__link:hover { background-color: #21262d !important; }
  /* Keyboard traversal marks the current row with .focused, not :hover — a #f1f2f3 tint in
     the results list and a full #fff in the suggestions list. Rows also separate with a
     #dcdddf dotted ::before, and each section header hangs a 1px #dcdddf ::before bar; both
     are pseudo-drawn, so the blanket border reset cannot reach either. */
  .search_results__item.focused,
  .search_results__suggestions .search_results__item.focused { background-color: #21262d !important; }
  .search_results__item + .search_results__item .search_results__details::before,
  .search_results__header::before { border-top-color: #2d333b !important; background-color: #2d333b !important; }
  /* The panel's "View all results for '<q>'" strip is an UNCLASSED <footer> (#f9f9fb) —
     no search_results__* class reaches it, and the footer rule above deliberately drops
     the bare `footer` selector, so it is the one light band left in the flyout. */
  .search_results > footer, .global-search footer, #global-search footer {
    background-color: #1c2128 !important; border-color: #2d333b !important; }
  /* Autocomplete result avatars are the same transparent-cutout-on-a-solid-white-disc
     component the theme already darks as .headshot — but the list variant is classed
     .headshot-sm, which that rule never matched, so every player row shipped a glaring
     white circle on the dark panel. At 30px they also duck the audit's size filter.
     Slightly above the panel so the disc still reads as an avatar. ---- */
  .search_results__img, .headshot-sm { background-color: #21262d !important; }
  /* Next-gen global-nav search (.Typeahead*, replaces the legacy .search_results): the
     results panel rides .bg-clr-white so it darks, but the two control icons —
     .TypeaheadControls__Submit (magnifier) and .TypeaheadControls__Clear (×) — are SVGs
     hardcoding a WHITE box with a BLACK glyph. Native ESPN's white nav hid the boxes;
     on our dark search bar they glare as two white squares. Transparent box + light
     glyph. Audit-blind: the search bar collapses to a toggle until the icon is tapped. */
  .TypeaheadControls__Submit, .TypeaheadControls__Clear,
  .TypeaheadControls__Submit *, .TypeaheadControls__Clear * {
    background-color: transparent !important; fill: #c4cdd6 !important; }
  /* The open search field's backdrop is a WHITE .Typeahead__Wrapper::before (306×40),
     not the input's own bg (which we dark) — the input covers most of it, but the strip
     to the left of the input, behind the magnifier, and the sliver past its right edge
     show the white ::before as a glaring box on our dark nav. Native ESPN's white nav hid
     it. Doubly audit-blind: a pseudo-element (no box bg, no text node) that only exists
     once the search is opened. Dark it to the field surface. */
  .Typeahead__Wrapper::before { background-color: #1c2128 !important; }

  /* ---- Account flyout (li.user > .global-user): white panel + a lighter
       #f1f2f3 "Favourites" pane whose copy is a pale grey → invisible on white
       AND unreadable once only the panel is darked. Dark both, lift the text. ---- */
  .global-user, .global-user-container, .display-user,
  .global-user .favs, .global-user .favs__container {
    background-color: #1c2128 !important; border-color: #2d333b !important; }
  .global-user .favs { background-color: #181d23 !important; }
  .global-user .favs, .global-user .favs p, .global-user .favs h3,
  .global-user .favs span, .global-user h3 { color: #c4cdd6 !important; }
  /* "Create Account" inside the flyout's Favourites pane is a FILLED brand-blue .button
     (#3772df/white) — the only action in the pane — and the neutral .button rule above
     flattened it to the same grey pill as an ordinary control. Same treatment as the
     sideLogin primary. Audit-blind: the flyout does not render until the avatar is
     clicked. */
  .button.open-favs, .global-user .button.open-favs {
    background-color: #588ae4 !important; border-color: #588ae4 !important;
    color: #121213 !important; -webkit-text-fill-color: #121213 !important; }
  .button.open-favs:hover, .global-user .button.open-favs:hover {
    background-color: #7aa1ea !important; }

  /* ---- Video-playlist modules ("Top Videos" / "NBA Videos") — white tiles ---- */
  .mediaList, .mediaList__content, .mediaList__link, .video-playlist,
  .video-playlist-item, li.video-playlist-item, .MediaList, .MediaList--highlights,
  .MediaList__list, .MediaList__item, .MediaList__item__wrap, .MediaList__content,
  .VideoList, .VideoPlaylist, .playlist, .playlist__item, .videoPlaylist__item {
    background-color: #1c2128 !important; border-color: #2d333b !important; }
  .mediaList__link:hover, .MediaList__item:hover, .video-playlist-item:hover,
  .playlist__item:hover { background-color: #21262d !important; }
  .mediaList__title, .MediaList__title, .MediaList__item__description,
  .video-playlist-item__title, .playlist__item__title, .mediaList__link h3,
  .MediaList__item h3 { color: #e6edf3 !important; }
  .mediaList__duration, .MediaList__duration, .MediaList__item__time,
  .MediaList__item__meta, .video-playlist-item__duration,
  .playlist__item__duration, .video-duration { color: #9aa4ae !important; }

  /* ---- Scores carousel: light band past the last chip (#f1f2f3) ---- */
  .scores-carousel, .scores-carousel .wrap, .scoreboard-content .wrap,
  .scores-carousel__inner, .scoreLabel_content, .scoreboard-wrapper, .web-scoreboard,
  .HeaderScoreboard, .HeaderScoreboard--empty, #global-scoreboard .wrap,
  .HeaderScoreboard__Wrapper .wrap {
    background-color: #14181d !important; }
  /* Scoreboard-strip odds-sponsor tile (.view-sponsor, "Odds by bet365"): a hardcoded
     #f1f2f3 70x65 box pinned at the left of the strip, so it glares as a white card in
     the dark header band. Its own logo is a self-contained green badge and survives the
     darker surround. Audit-blind: the tile is under the big() size floor, and it only
     renders on pages whose strip carries an odds slot. */
  a.view-sponsor, .view-sponsor { background-color: #1c2128 !important; }

  /* ---- Misc surfaces that default to white ---- */
  .bg-clr-white, .bg-white, [class*="bg-clr-white"] { background-color: #1c2128 !important; }
  /* Sport "Teams" index page (Football/NBA/NFL > Teams): the whole team-directory
     panel is a hardcoded-white .TeamsWrapper (.Wrapper is transparent; the white is
     on .TeamsWrapper) filling the main column — our already-light team names + section
     heading then render light-on-white, near-invisible, while the header/scoreboard/
     sidebar around it stay dark. Not a bg-clr-white class, so the white-surface rule
     misses it; audit-blind because the SPA route strips the inject on the Teams click,
     so a load-time scan of the re-injected page is the only way to see it. */
  .TeamsWrapper { background-color: #1c2128 !important; }
  /* Schedule group header band (team page left rail) hardcodes a near-white
     bg-clr-gray-10 (#f9f9fb) under our already-light title text → light-on-light. */
  .Schedule__Group__Title { background-color: #1c2128 !important; }
  /* Story-body <hr> is painted by its BACKGROUND (#dcdddf), not its border, so a
     border-only override left a bright white hairline across the article. */
  hr { border-color: #2d333b !important; background-color: #2d333b !important; }
  /* Pseudo-element divider lines ESPN paints with a near-white #dcdddf bar
     (footer column rule + news-feed item separators) — invisible to a bg-color
     scan; remap to our divider grey. ---- */
  .PageFooter__QuickLinks::after, .news-feed-item::before,
  .mediaList__link::after { background-color: #2d333b !important; }
  /* The one-feed draws its intra-card rules as pseudo-element BORDERS in the same #dcdddf
     (quick-links rows, the underline below a card heading, the rule above a card's action
     strip, and the separator between mobile score cards) — the blanket `*` border reset
     cannot reach a pseudo, so each renders as a bright hairline across the dark card. */
  .quicklinks_list__item::after, .contentItem__header::after,
  .contentItem__footer::before, .cscore::before {
    border-color: #2d333b !important; }
  ::selection { background-color: #2f6fb8 !important; color: #ffffff !important; }

  /* ---- Filter controls (season / round / view dropdowns, segmented ButtonGroup) ---- */
  .dropdown, .dropdown--md, .dropdown--sm, .dropdown--lg, .ButtonGroup,
  .filters__seasonDropdown, .pageHeading__team-stats-dropdown {
    background-color: #1c2128 !important; border-color: #2d333b !important; }

  /* ---- Player page: header image container + "Switch Player" flyout (default white) ---- */
  .PlayerHeader__Image_Container, [class*="PlayerHeader__Image"] { background-color: #1c2128 !important; }
  /* Diagonal header divider panels ship solid white over the dark header → dark them. */
  .PlayerHeader__Overlay, .PlayerHeader__Overlay--left, .PlayerHeader__Overlay--right {
    background-color: #1c2128 !important; }
  /* Follow CTA (player + team clubhouse): a FILLED brand-blue button (#3772df, white
     label) natively — the ONLY prominent action in the header. Its blue fill resolves
     through the same surface token we darken elsewhere, so it collapsed to a dark #1c2128
     ghost pill (and its label to dark), erasing the primary-CTA identity. Restore a filled
     blue: reuse the theme's dark-appropriate ESPN-blue pairing (#588ae4 on near-black),
     matching the sideLogin / flagship CTAs. */
  .PlayerHeader__Follow, .ClubhouseHeader__Follow {
    background-color: #588ae4 !important; border-color: #588ae4 !important;
    color: #121213 !important; -webkit-text-fill-color: #121213 !important; }
  /* Shortstop-card "Follow" CTA. ESPN writes it `var(--bg-surface-raised, <brand blue>)` and
     leaves --bg-surface-raised undefined outside .theme-espnDS_v2, so the fallback IS the
     paint; the token block below defines that token on .theme-light too, which swaps the
     brand fill for the card surface and turns the card's only action into a ghost pill. */
  .ctaButton {
    background-color: #588ae4 !important; border-color: #588ae4 !important;
    color: #121213 !important; -webkit-text-fill-color: #121213 !important; }
  /* Game-note strip ("NBA Finals - Game 5, NY wins series") paints pure black → muted grey. */
  .ScoreCell__GameNote, .ScoreCell__NotesWrapper { color: #9aa4ae !important; }
  /* Upcoming-fixture DATE in a Gamestrip ScoreCell ("Next Match" on the player/team
     page) paints near-black #121213 — legible on the site's white card, 1.05:1 on our
     base, i.e. flat invisible, while the kickoff TIME right below it stays readable.
     Match the time's muted grey. */
  .ScoreCell__ScoreDate { color: #9aa4ae !important; }
  .SwitchPlayer, .SwitchPlayer__list, .SwitchPlayer__athletes, [class*="SwitchPlayer"] {
    background-color: #1c2128 !important; border-color: #2d333b !important; }
  .SwitchPlayer__athlete_link:hover { background-color: #21262d !important; }
  .SwitchPlayer__athlete_link, .SwitchPlayer__athlete_link span,
  [class*="SwitchPlayer__athlete"] { color: #c4cdd6 !important; }

  /* ---- Header-scoreboard event cards (e.g. live golf "spotlight") that go white ---- */
  .HeaderEvent { background-color: #1c2128 !important; border-color: #2d333b !important; }
  .ScoreCell__NetworkItem { color: #9aa4ae !important; }
  /* live/in-progress HeaderEvent spotlight (.HeaderEvent--in, e.g. a live golf major)
     paints its event-name headline in ESPN live-red #dd0000 — ~3.1:1 on our darkened
     #1c2128 chip (readable at ~5:1 on the site's original white). Lift to a brighter
     red so it clears AA while staying a live-red accent. ---- */
  .HeaderEvent--in .HeaderEvent__Headline {
    color: #ff5a5a !important; -webkit-text-fill-color: #ff5a5a !important; }

  /* ---- Search results page: the React page wrapper (#themeProvider > breakpoint
       div) + the search-input wrapper (.SearchBar) ship a solid WHITE panel behind
       the search field + filter-pill row (content cards cover the rest, so a bg-color
       scan of the cards passes while the header band glares white). Dark to base. ---- */
  #themeProvider > div, .SearchBar { background-color: #14181d !important; }
  /* The search field's edge is a two-sided inset #eeeff1 bevel (box-shadow, not a border):
     invisible on ESPN's white bar, a hard bright corner on ours. Even it out. */
  .SearchBar { box-shadow: 0 0 0 1px #2d333b inset !important; }
  /* ---- Search results: filter pills + video duration badge ---- */
  .Pill { background-color: #21262d !important; border-color: #2d333b !important; color: #c4cdd6 !important; }
  .Pill--selected { background-color: #2d333b !important; color: #e6edf3 !important; }
  .MediaPlaceholder__Pill { background-color: rgba(13,17,23,0.78) !important; color: #ffffff !important; }
  /* Search player-result tiles: team/league subtitle hardcodes #6c6d6f → dark-on-dark */
  .LogoTile__Meta, .LogoTile__Meta--subtitle, .LogoTile__Meta--category { color: #9aa4ae !important; }

  /* ---- Taboola "sponsored content" wrapper (hyphenated class variant). The
       right-rail mount carries its white inline on an ID with no class at all
       (div#taboola-right-rail---dead-end---sport, style="background-color:
       rgb(255,255,255)"), and the article-foot widget on .trc_related_container /
       .tbl-feed-container — neither reachable via [class*="taboola"]. ---- */
  .sponsored-headlines, .trc_rbox, .trc_rbox_div, [class*="taboola"],
  [id*="taboola"], .trc_related_container, .tbl-feed-container {
    background-color: #14181d !important; }
  /* Taboola sponsored-widget CTA pill ("Learn more") hardcodes near-black text
     → invisible on our dark surround; lighten just the label. ---- */
  .video-cta-button, .video-cta-href { color: #c4cdd6 !important; }
  /* Taboola feed cards separate with a BOX-SHADOW, not a border or a background:
     `box-shadow: 0 1px 0 0 #e6ecf0`. No border-color reset and no background rule can
     reach it, so each card ships a bright white rule across the dark sponsored rail. */
  .tbl-feed-card { box-shadow: 0 1px 0 0 #2d333b !important; }

  /* ---- Golf scoreEvent metadata (hardcodes #48494a via class) ---- */
  .scoreEvent__concludings { color: #9aa4ae !important; }

  /* ---- Game-strip team-colour header band. The band is a two-team brand GRADIENT
       (background-image: linear-gradient(to right, <teamA>, <teamB>)) carrying a white
       competition label. brightness(0.5) darkened the gradient AND every glyph inside
       it, and the generic span rule had already greyed the label to #c4cdd6 — together
       they rendered it #626a6b on a muddied maroon, ~2.9:1, failing AA on a band that
       is perfectly legible (white-on-brand) natively. A filter cannot spare its own
       text, so drop it and restore the native white label: the saturated team gradient
       is exactly the brand colour this theme promises to preserve. ---- */
  .game-details.header.sm { filter: none !important; }
  .game-details.header.sm, .game-details.header.sm span,
  .game-details.header.sm .cscore_notes_game {
    color: #ffffff !important; -webkit-text-fill-color: #ffffff !important; }

  /* ---- Live-game "AutoGameBlock" (.game-strip.live "LAST PLAY" panel on section
       pages): the top team strip is themed via .game-strip, but the LAST PLAY sub-panel
       ships a solid WHITE container + a white/#f1f2f3 image well with white MASK overlays
       (fading a team-jersey watermark), and the play description hardcodes #1d1e1f via
       .AutoGameBlock__Text (a class, so the inline-#1d1e1f catch-all misses it) → black
       on white. Dark the panels; lift the play text. The "Last Play" title is already
       our light heading colour. Audit-blind: each cell is <90px tall. ---- */
  .AutoGameBlock, .AutoGameBlock--in, .AutoGameBlock__Body, .AutoGameBlock__Image,
  .AutoGameBlock__Mask, .AutoGameBlock__Mask--opaque {
    background-color: #1c2128 !important; border-color: #2d333b !important; }
  .AutoGameBlock__Text { color: #c4cdd6 !important; }
  /* Live-game clock in the strip header (.game-strip.live .game-time, "0:32 - 2nd") is
     ESPN's live-red #dd0000 — the same in-progress signal the theme reds on the legacy
     scoreboard (.cscore--live) and one-feed (.scoreEvent--live). Our a-span link rule
     flattened it to blue, so a live game read identical to a scheduled kickoff. Scope to
     .live so scheduled/final strips keep their neutral time. */
  header.game-strip.live .game-time, .game-strip.live .game-time {
    color: #ff5a5a !important; -webkit-text-fill-color: #ff5a5a !important; }

  /* ---- Next-gen "prism" design system (espnDS_v2): gamecast / match / newer layouts.
       Fully token-driven — remap surface tokens (white -> dark) and text tokens
       (dark -> light). Deploy-stable: targets the design-system theme wrappers, not
       the hashed component classes. ---- */
  .theme-espnDS_v2, .theme-espnDS_v2Remaps, .next-gen-gamecast, .theme-nextGenGamecast,
  .theme-light, .theme-espn {
    --layoutCard-background-color: #1c2128 !important;
    --bg-surface-raised: #1c2128 !important;
    --surface-background-color: #14181d !important;
    --base-background-content: #14181d !important;
    --bg-surface-canvas: #14181d !important;
    --selectors-background-resting: #21262d !important;
    --selectors-background-hover: #2d333b !important;
    --selectors-background-focus: #2d333b !important;
    --inputs-background-resting: #1c2128 !important;
    --inputs-background-hover: #21262d !important;
    --inputs-background-focus: #1c2128 !important;
    --bracket-pills-backgroundColor: #21262d !important;
    --bracket-periodNavigator-background: #1c2128 !important;
    --commercePromo-backed-background: #1c2128 !important;
    --base-text-primary: #e6edf3 !important;
    /* next-gen gamecast muted-text combos: box-score stat lines (#6c6e6f), matchup
       records (#5a5c5d) and team abbreviations (#48494a) resolve color through these
       combo tokens → dark-on-dark. Remap to readable muted grey. */
    --color-combo-neutral-low: #9aa4ae !important;
    --color-combo-gray60-gray50: #9aa4ae !important;
    --color-combo-disableddark-graychateau: #9aa4ae !important;
    --betSixPack-teamRecord-color: #9aa4ae !important;
    --card-content-color: #c4cdd6 !important;
    /* neutral-50 (#f9f9f9) is the lightest surface tint — drives the next-gen
       gamecast Game-Odds panel + DraftKings odds cells white (bg-only, never text). */
    --color-neutral-50: #1c2128 !important;
    --color-neutral-100: #21262d !important;
    --border-divider-weak: #2d333b !important;
    --color-combo-cultured-eerieblack: #1c2128 !important;
    --color-neutral-900: #e6edf3 !important;
    --color-neutral-850: #c4cdd6 !important;
    --color-neutral-800: #c4cdd6 !important;
    --color-neutral-700: #9aa4ae !important;
    --color-neutral-600: #9aa4ae !important;
    --text-weak: #9aa4ae !important;
    --text-weaker: #9aa4ae !important;
    --color-combo-mattegraphite-smoothgrey: #9aa4ae !important;
    --color-status-neutral: #9aa4ae !important;
    --color-status-disabled: #6e7681 !important;
    --icon-action-tertiary-default: #c4cdd6 !important;
    --color-combo-gray80-csilver: #e6edf3 !important;
    --color-combo-gray80-white: #e6edf3 !important;
    --color-combo-gray80-gray30: #e6edf3 !important;
    --color-combo-gray80-gray40: #e6edf3 !important;
    --color-combo-gray80-disabledlight: #9aa4ae !important;
    --color-combo-gray90-white: #e6edf3 !important;
    --color-combo-gray100-white: #e6edf3 !important;
    --color-combo-gray100-gray10: #e6edf3 !important;
    /* black-on-light text combos (gamecast Gamestrip winner score numeral + box-score
       team abbreviations paint pure black via --color-combo-black-white) → light */
    --color-combo-black-white: #e6edf3 !important;
    --color-combo-black-gray85ish: #e6edf3 !important;
    --color-combo-black-gainsboro: #e6edf3 !important;
    --color-combo-black-cultured: #e6edf3 !important;
    /* white-in-light surface combos (gamecast line-score table body cells paint white
       via --color-combo-white-gray90) → dark elevated surface */
    --color-combo-white-gray90: #1c2128 !important;
    --color-combo-white-gray100: #1c2128 !important;
    --color-combo-white-graybunker: #1c2128 !important;
    --color-combo-white-oreo: #1c2128 !important;
    --color-combo-oreo-white: #e6edf3 !important;
    --color-combo-oreo-gray85ish: #e6edf3 !important;
    --color-combo-themeDark-themeLight: #e6edf3 !important;
    --color-combo-themeDark-white: #e6edf3 !important;
    --color-combo-gray80-grayChateau: #9aa4ae !important;
    --color-combo-grayabbey-graychateau: #9aa4ae !important;
    /* DraftKings odds-widget disclaimer note (.NIhmB "Odds and lines subject to
       change") = --color-combo-gray60-gray40 (#6c6e6f) → ~3:1 dark-on-dark. */
    --color-combo-gray60-gray40: #9aa4ae !important;
    --color-combo-cobaltblue-pictonblue: #5fb0e6 !important;
    --color-combo-blue80-blue30: #5fb0e6 !important;
    --byline-contributorLinkActive-color: #5fb0e6 !important;
    --byline-contributorLinkHover-color: #9bd4ff !important;
    /* ESPN's newest design-system layer ("fusion", declared on .theme-espnDS_v2 itself)
       is a second, semantic token set on top of the combo tokens above. Its LIGHT values
       ship on every next-gen page; --text-default alone is `#000`, which paints the
       gamecast Gamestrip winning score, the match-leader stat lines and every news-rail
       description pure black on our dark cards. ESPN publishes its own dark values in
       .theme-espnDS_v2Dark — mirror those, translated to this theme's palette. */
    --text-default: #c4cdd6 !important;
    --text-disabled: #6e7681 !important;
    --text-inputs-default: #ffffffb8 !important;
    --text-inputs-disabled: #6e7681 !important;
    --text-action-secondary-default: #c4cdd6 !important;
    --text-status-success: #4ac76a !important;
    --text-status-live: #ff5a5a !important;
    --text-hyperlink: #5fb0e6 !important;
    --text-action-hyperlink-default: #5fb0e6 !important;
    --text-action-hyperlink-hover: #9bd4ff !important;
    --icon-default: #c4cdd6 !important;
    --icon-weak: #9aa4ae !important;
    --bg-surface-floating: #1c2128 !important;
    --bg-status-neutral: #21262d !important;
    --bg-action-secondary-hover: #21262d !important;
    --bg-action-secondary-pressed: #1c2128 !important;
    --bg-action-option-default: #1c2128 !important;
    --bg-action-tertiary-hover: #ffffff14 !important;
    --bg-action-tertiary-pressed: #ffffff1f !important;
    --interaction-alpha-weaker: #ffffff0a !important;
    --color-alpha-black-12: #ffffff1f !important;
    --border-surface-default: #2d333b !important;
    --border-surface-secondary-default: #2d333b !important;
    --border-divider-default: #2d333b !important;
    --border-inputs-default: #ffffff5c !important;
    --border-inputs-hover: #8b949e !important;
    --border-option-off-default: #8b949e !important;
    --border-table-default: #2d333b !important;
    --dataViz-progress-background: #3a4149 !important;
    --dataViz-table-tableHighlight: #21262d !important;
    --dataViz-table-tableDivider: #2d333b !important;
    /* Remaining --color-combo-* pairs. The token NAME is `<light-value>-<dark-value>` and
       ESPN ships the dark half in .theme-espnDS_v2RemapsDark; only the light half was
       covered above, so every one of these still resolved to its LIGHT value. Kept to the
       pairs whose light value is a light SURFACE or a near-black TEXT (a mid-grey reads
       acceptably either way), each set to ESPN's own dark value in this theme's palette —
       e.g. --color-combo-gray85ish-graybunker drives the soccer lineup's striped rows and
       --color-combo-white-gray80 the match-timeline event discs. */
    --color-combo-americansilver-gray75: #3a4149 !important;
    --color-combo-blue10-blue100: #0d2450 !important;
    --color-combo-blue10-blue90: #133778 !important;
    --color-combo-disabledDark-grayChateau: #9aa4ae !important;
    --color-combo-disableddark-white: #e6edf3 !important;
    --color-combo-eplus10-eplus100: #533b00 !important;
    --color-combo-favorite-favoritedark: rgba(255,245,0,.1) !important;
    --color-combo-ghostwhite-ashGray: #21262d !important;
    --color-combo-ghostwhite-black: #14181d !important;
    --color-combo-ghostwhite-gray90: #1c2128 !important;
    --color-combo-gray10-gray100: #14181d !important;
    --color-combo-gray10-gray80: #21262d !important;
    --color-combo-gray10-gray90: #1c2128 !important;
    --color-combo-gray20-black: #14181d !important;
    --color-combo-gray20-gray100: #14181d !important;
    --color-combo-gray20-gray40: #9aa4ae !important;
    --color-combo-gray20-gray70: #6e7681 !important;
    --color-combo-gray20-gray75: #3a4149 !important;
    --color-combo-gray80u-graychateau: #9aa4ae !important;
    --color-combo-gray85ish-ashgray: #21262d !important;
    --color-combo-gray85ish-black: #14181d !important;
    --color-combo-gray85ish-gray80: #21262d !important;
    --color-combo-gray85ish-graybunker: #21262d !important;
    --color-combo-gray85ish-oreo: #14181d !important;
    --color-combo-iron-ashGray: #21262d !important;
    --color-combo-iron-ashgray: #21262d !important;
    --color-combo-iron-disableddark: #4a525b !important;
    --color-combo-iron-gray75: #3a4149 !important;
    --color-combo-iron-gray80: #21262d !important;
    --color-combo-iron-stormyGray: #3a4149 !important;
    --color-combo-lightsilver-galaxyblack: #21262d !important;
    --color-combo-porcelain-black: #14181d !important;
    --color-combo-smoothgrey-galaxyblack: #21262d !important;
    --color-combo-snow-eerieblack: #14181d !important;
    --color-combo-themeLight-gray80: #21262d !important;
    --color-combo-themeLight-themeDark: #14181d !important;
    --color-combo-white-black: #1c2128 !important;
    --color-combo-white-disableddark: #4a525b !important;
    --color-combo-white-gray80: #21262d !important;
    --color-combo-white-pictonblue: #4c99e6 !important;
  }
  /* Gamestrip score header (next-gen) paints via --color-neutral-0 (shared with white
     text) so we dark it through its stable container instead of the token. */
  .Gamestrip, .Gamestrip__Container, .Gamestrip__StickyContainer { background-color: #14181d !important; }
  .Gamestrip__Container > div { background-color: #14181d !important; }
  .Media__Caption, .Media__Caption--card { background-color: #1c2128 !important; }
  /* Next-gen "light theme" cards that hardcode a white panel bg (gamecast recap /
     GameStory card) — the token remap above darks token-driven surfaces, but these
     paint white directly. Scope to the light-theme wrapper so feed cards elsewhere
     are untouched. ---- */
  .theme-light .contentItem__content, .theme-light .contentItem__contentWrapper,
  .theme-light .GameStory, .GameStory .contentItem__content { background-color: #1c2128 !important; }
  /* Prism segmented control (gamecast Matchups "Regular Season / Playoffs" toggle):
     the track paints a light grey (#c7c7c9) and the ACTIVE segment a hardcoded white
     pill (shared --color-neutral-0, not token-remappable) with light text → unreadable.
     Dark the track + active pill via stable role/data-testid selectors. ---- */
  [data-testid="prism-tab-list"] [role="tablist"] {
    background-color: #14181d !important; border-color: #2d333b !important; }
  [data-testid="prism-tab-list"] [role="tab"],
  [data-testid="prism-ButtonBase"][role="tab"] { background-color: transparent !important; color: #9aa4ae !important; }
  [data-testid="prism-tab-list"] [role="tab"][aria-selected="true"],
  [data-testid="prism-ButtonBase"][role="tab"][aria-selected="true"] {
    background-color: #2d333b !important; color: #e6edf3 !important; }
  /* Gamecast shot-chart hover tooltip ships a white panel (+ white caret pseudo)
     with light text → unreadable on hover; dark the panel and its arrow. */
  .ShotChart__Court__Play__Tooltip {
    background-color: #1c2128 !important; color: #e6edf3 !important; border-color: #2d333b !important; }
  .ShotChart__Court__Play__Tooltip::before, .ShotChart__Court__Play__Tooltip::after {
    background-color: #1c2128 !important; border-color: #1c2128 !important; }
  /* Shot-chart / play-by-play mini-court markers: a MISSED shot is a hollow white disc with
     the team-colour ring, a MADE shot a solid team-colour disc — both carry the value inline,
     so the inline-white catch-all darkened every missed marker. The court itself is a light
     brand graphic we never darken, and ESPN gives an achromatic team the near-black #1d1e1f,
     so made and missed collapsed into two identical dark dots. Keep missed white. */
  .ShotChart__Court__Play:not(.ShotChart__Court__Play--made) {
    background-color: #ffffff !important; }
  /* Gamecast Game-Odds (DraftKings) odds cells: the value text hardcodes pure black
     (--color-neutral-1000) — fine on the original white cell, dark-on-dark once the
     cell surface is darked. Light the cell text via the stable testid. */
  [data-testid="OddsCell"] {
    background-color: #1c2128 !important; border-color: #2d333b !important; }
  [data-testid="OddsCell"], [data-testid="OddsCell"] * {
    color: #e6edf3 !important; -webkit-text-fill-color: #e6edf3 !important; }
  /* Soccer shot-card goal-mouth outcome badge ("Goal"/"Saved"/"Blocked"/"Off Target")
     sits on a red/green chip; its label resolves through --color-combo-white-gray90,
     which we dark as a SURFACE elsewhere → dark-on-color label. Force white in scope. */
  .ShotCard__GoalMouth, .ShotCard__GoalMouth * {
    color: #ffffff !important; -webkit-text-fill-color: #ffffff !important; }

  /* ---- MLB baseball gamecast live-tracker widget (.Gamecast__Baseball): the
     batter/pitcher header, pitch-zone surround, on-base strip and pitch-list rows
     ship a solid WHITE panel (hardcoded, not token-driven) with grey text → a
     glaring white block mid-gamecast. Dark the panels; the colored strike-zone
     cells and batter illustration are separate children and stay intact. ---- */
  .Gamecast__Baseball, .Gamecast__Baseball .StatusBar__Slide,
  .Gamecast__Baseball .StatusBar__Module__BatterPitcher,
  .Gamecast__Baseball .StatusBar__Module__PlayerIntro,
  .OnBase__Wrapper, .PitchTracker__Pitch {
    background-color: #1c2128 !important; border-color: #2d333b !important; }
  .Gamecast__Baseball .headshot { background-color: #1c2128 !important; }
  /* empty base-indicator square (.FieldView__Square--hidden) was white-on-white
     and camouflaged; darking the widget exposes it → let the dark panel show. */
  .FieldView__Square--hidden { background-color: transparent !important; }
  /* Pitch-count balls/strikes/outs indicator (.PitchCount__Orb): the EMPTY orb ships a
     solid WHITE fill (invisible against ESPN's white panel — reads as a hollow red-ringed
     slot) while the --filled orb is a coloured disc. On our dark panel the white empty orb
     glares as a solid disc that reads as LIT, so a 0-0 count renders like a full 4-3 count.
     Blank the empty orb to a hollow dark slot with a muted ring; leave --filled to ESPN's
     own count colour so the lit orbs stay the signal. Audit-blind: 8px orbs slip the size
     filter and the white was masked on the native white panel. ---- */
  .PitchCount__Orb:not(.PitchCount__Orb--filled) {
    background-color: transparent !important; border-color: #4a525b !important; }
  /* Same indicator one component over — the SCOREBOARD's .BaseballSituation widget uses
     .pitches .circle, not .PitchCount__Orb. ESPN fills a lit orb through a design token
     (#dd0000 outs/strikes, #009944 balls); the theme's token block remaps that token to
     the card surface, so a lit orb rendered IDENTICAL to an unlit one and the whole
     ball/strike/out count disappeared. The .green modifier needs three classes to clear
     the two-class red rule. The unlit orb's #cbccce ring is flattened by the blanket `*`
     border reset to #262c33 (~1.05:1 on the card) — lift it so the empty slots still
     read as slots. Audit-blind: 10px, and the loss is semantic, not luminance. */
  .pitches .circle.active {
    background-color: #dd0000 !important; border-color: #dd0000 !important; }
  .pitches .circle.active.green {
    background-color: #009944 !important; border-color: #009944 !important; }
  .pitches .circle:not(.active) { border-color: #4a525b !important; }
  /* Base-occupancy diamonds in the same widget: ESPN encodes a runner on base with its
     link-blue border utility (.brdr-clr-link) against the empty base's .brdr-clr-gray-06,
     and the `*` border reset collapsed both to one grey — every base read as empty. The
     home page's legacy .cscore diamonds carry neither utility class (they colour a single
     border-bottom from a .base-<n>-<n>-<n> parent, with !important, so they survive), which
     is why this only breaks on the SPA scoreboard. */
  .diamond.brdr-clr-gray-06 { border-color: #4a525b !important; }
  .diamond.brdr-clr-link { border-color: #5fb0e6 !important; }
  /* the StatusBar carousel transition panes paint a full-size white ::before */
  .StatusBar__TransitionPane::before, .StatusBar__TransitionPane::after {
    background-color: #1c2128 !important; }
  /* win-probability chart legend team names + gamecast weather temp hardcode
     near-black text (dark-on-dark once their surface is darked). */
  .CustomLegend__TeamName { color: #e6edf3 !important; }
  /* The .CustomLegend container hands its children a near-black #121213; the team name is
     lifted above, but the percentage label beside it is a <div> and inherits it. */
  .CustomLegend__Team__Percent { color: #c4cdd6 !important; }
  .Weather__Temp, .Weather__Items, .Weather__HiLow { color: #c4cdd6 !important; }
  /* Recharts axis tick labels (win-probability graph, drive charts) paint #5a5c5d through a
     `fill` presentation attribute, so neither the token remaps nor any `color` rule reaches
     them — ~2.4:1 on the card. Only the axis scale is targeted; the data series keep their
     team colours. */
  .recharts-cartesian-axis-tick text, .recharts-cartesian-axis-tick tspan,
  .recharts-cartesian-axis-tick-value { fill: #9aa4ae !important; }
  /* light-grey divider in the top scoreboard-strip ScoreCells (#cecfcf ::after); the
     mobile scoreboard score cell draws the same #cecfcf rule as .ScoreCell__Overview::before
     between the score and the status/Highlights column. */
  .ScoreCell__CompetitorDetails::after,
  .ScoreCell__Overview::before, .ScoreCell__Overview::after { background-color: #2d333b !important; }
  /* gamecast WIN/LOSS pitcher pair (.Athletes__Container) is split by a light-grey
     #cecfcf ::after vertical divider → light hairline on the dark card; remap to the
     theme divider grey. Audit sees it as a pseudo-white but it's a thin rule. ---- */
  .Athletes__Container .Athlete::after, .Athletes__Container .Athlete::before {
    background-color: #2d333b !important; }

  /* ---- More light hairlines painted by pseudo-elements (#edeef0): the vertical
       rule inside every scoreboard-strip game chip and the scores-carousel label
       underline. Thin, so they slip the audit's size filter. ---- */
  .cscore_overview::before, .cscore_overview::after,
  .scoreLabel_content::before, .scoreLabel_content::after {
    background-color: #2d333b !important; }
  /* Same hairline one row down: every one-feed leaderboard row (golf/tennis scoreEvent)
     separates its score column from its today/movement column with a 1px #edeef0
     ::after on the row anchor — a bright white rule the full height of the leaderboard.
     1px wide, so it slips the audit's size filter, and it is a pseudo, so no element-bg
     scan can see it at all. ---- */
  .cscore_link::after { background-color: #2d333b !important; }

  /* ---- 404 page ships its own white hero panel + near-white quick-links block
       (with our already-light headline text on top → light-on-light). ---- */
  .Error404, .Error404__Wrapper, .Error404__QuickLinks {
    background-color: #14181d !important; border-color: #2d333b !important; }
  .Error404__QuickLinks::before, .Error404__QuickLinks::after {
    background-color: #2d333b !important; }

  /* ---- Story bodies embed a RASTER divider (a.espncdn.com/i/.../greyline.png):
       a light bar image, so no background rule can touch it. Invert it into a dark
       rule that reads as a divider on our base. ---- */
  img[src*="greyline"] { filter: invert(1) !important; }

  /* ---- Story "Share" flyout (.share-popup, opened by the byline Share button): a
       solid #fff card with #1d1e1f ink, `display:none` until the button adds
       .popup-active — invisible to every load-time scan. Our light body ink then
       rendered Email / Print as pale grey ON WHITE while the li dividers went black.
       ESPN ships its own dark half ([data-appearance='dark'] → #2b2c2d/#f9f9fb), so
       mirror it at the theme's floating-surface colour. The item anchors are
       `color: inherit !important` in ESPN's sheet, so setting the PANEL's colour is
       what actually repaints them — a rule on .share-popup-link loses the tie. The
       copy-link success state hardcodes #0D830F (3.3:1 on our card); lift it. ---- */
  .share-button-wrapper .share-popup {
    background-color: #1c2128 !important; color: #e6edf3 !important; }
  .share-button-wrapper .share-popup .copy-link.active-copy-link .copy-link-inner {
    color: #4ac76a !important; -webkit-text-fill-color: #4ac76a !important; }

  /* ---- One-feed game-strip out count: ESPN paints the LIVE clock (.game-time) red and
       leaves the "0 Outs" span inside it neutral ink. Our live-red rule sets
       -webkit-text-fill-color, which INHERITS into that child and overrides its own
       `color`, so the out count rendered as a second red live badge. A direct
       declaration on the child beats the inherited fill. ---- */
  .game-strip__outs {
    color: #c4cdd6 !important; -webkit-text-fill-color: #c4cdd6 !important; }

  /* ---- Batter hot/cold zone (.HitMap, MLB gamecast): each cell paints a saturated
       blue/red brand fill with a WHITE batting average in a bare unclassed <span>.
       Our generic `span { color: #c4cdd6 }` rule repaints it to grey → 2.1:1 on the
       red cells. Restore white-on-brand, as the site renders it. ---- */
  .HitMap__Item, .HitMap__Item span {
    color: #ffffff !important; -webkit-text-fill-color: #ffffff !important; }

  /* ---- Prism <ProgressBar> (gamecast team-stat comparison bars): the TRACK is a
       hardcoded light grey (#cecfcf) — the team-colored fill is a child div, so
       darking the track keeps every brand color intact. Bars are 10px tall, well
       under the audit's height filter. ---- */
  [data-testid="prism-ProgressBar"] { background-color: #3a4149 !important; }

  /* ---- Win-probability graph legend swatch (.GraphHeader__ColorLegend): each team's
       little dash carries its TEAM colour via an inline --legend-color custom property
       (border-drawn). Our blanket * { border-color } greyed every swatch, so the legend
       no longer maps a colour to a team (CON's #f05023 orange went flat grey). Restore
       the swatch to its own inline colour. ---- */
  .GraphHeader__ColorLegend { border-color: var(--legend-color) !important; }
  /* An achromatic team gets ESPN's near-black #1d1e1f instead of a brand hue, so on the dark
     card its win-probability curve (an SVG gradient stroke) and its legend dash both vanish
     — the chart reads as if only one team were plotted. Lift just that one neutral to the
     light equivalent the theme already uses for #1d1e1f team-stat bars; chromatic team
     colours match neither selector and survive. */
  stop[stop-color="#1d1e1f"] { stop-color: #c4cdd6 !important; }
  .GraphHeader__ColorLegend[style*="#1d1e1f"] { border-color: #c4cdd6 !important; }

  /* ---- ESPNIcons glyphs drawn through ::before / ::after in ESPN's hardcoded darks
       (#2b2c2d, #48494a, #6c6d6f) or link-blue #0066cc. Doubly audit-blind: a
       pseudo-element has no box background and no text node, so neither a surface
       scan nor a colour scan sees it. On our dark chrome they land at 1.3–3.1:1 —
       the scoreboard carousel arrows, the sub-nav dropdown carets, the external-link
       markers and the filter-button caret were all effectively invisible. ---- */
  #global-scoreboard .scores-prev::before, #global-scoreboard .scores-next::before,
  .scoreCenter .scores-prev::before, .scoreCenter .scores-next::before,
  #global-nav-secondary .global-nav-container > ul > li.has-sub > a::after,
  #global-nav-secondary .tertiary-nav li.has-sub > a::after,
  .button-filter::before, .button-filter::after,
  .quicklinks_list__icon::before, .contentItem__content__meta::after,
  a.external::after, li.external > a::after { color: #9aa4ae !important; }

  /* ---- Card top rule: the legacy one-feed bar (.contentItem__teamBorder) and its
       Prism News-card successor (.ColorBorder) both carry the TEAM colour in an inline
       style; a card with no team gets a light neutral from ESPN's grey scale instead —
       a 3px hairline that glares across our dark cards (audit-blind: 3px slips the
       size floor). No CSS can test a colour for chroma, so the neutral fallbacks have
       to be enumerated. Two axes matter beyond the literal value, and both have shipped
       a miss: ESPN swaps WHICH grey it uses (#cbccce, then #FFFFFF, then #a5a6a7), and
       the same bar re-rendered client-side comes back as `rgb(165, 166, 167)` because
       the CSSOM re-serialises the attribute — on a team page the below-the-fold cards
       carry the rgb form while the SSR ones carry hex. So: the light achromatic rungs
       of ESPN's own palette, each in hex (both cases) and rgb (both spacings), on both
       classes. Chromatic team colours match none of these and survive verbatim. ---- */
  .ColorBorder[style*="#848687"], .contentItem__teamBorder[style*="#848687"],
  .ColorBorder[style*="rgb(132, 134, 135)"], .contentItem__teamBorder[style*="rgb(132, 134, 135)"],
  .ColorBorder[style*="rgb(132,134,135)"], .contentItem__teamBorder[style*="rgb(132,134,135)"],
  .ColorBorder[style*="#a5a6a7"], .contentItem__teamBorder[style*="#a5a6a7"],
  .ColorBorder[style*="#A5A6A7"], .contentItem__teamBorder[style*="#A5A6A7"],
  .ColorBorder[style*="rgb(165, 166, 167)"], .contentItem__teamBorder[style*="rgb(165, 166, 167)"],
  .ColorBorder[style*="rgb(165,166,167)"], .contentItem__teamBorder[style*="rgb(165,166,167)"],
  .ColorBorder[style*="#b5b7b7"], .contentItem__teamBorder[style*="#b5b7b7"],
  .ColorBorder[style*="#B5B7B7"], .contentItem__teamBorder[style*="#B5B7B7"],
  .ColorBorder[style*="rgb(181, 183, 183)"], .contentItem__teamBorder[style*="rgb(181, 183, 183)"],
  .ColorBorder[style*="rgb(181,183,183)"], .contentItem__teamBorder[style*="rgb(181,183,183)"],
  .ColorBorder[style*="#cbccce"], .contentItem__teamBorder[style*="#cbccce"],
  .ColorBorder[style*="#CBCCCE"], .contentItem__teamBorder[style*="#CBCCCE"],
  .ColorBorder[style*="rgb(203, 204, 206)"], .contentItem__teamBorder[style*="rgb(203, 204, 206)"],
  .ColorBorder[style*="rgb(203,204,206)"], .contentItem__teamBorder[style*="rgb(203,204,206)"],
  .ColorBorder[style*="#cfd0d1"], .contentItem__teamBorder[style*="#cfd0d1"],
  .ColorBorder[style*="#CFD0D1"], .contentItem__teamBorder[style*="#CFD0D1"],
  .ColorBorder[style*="rgb(207, 208, 209)"], .contentItem__teamBorder[style*="rgb(207, 208, 209)"],
  .ColorBorder[style*="rgb(207,208,209)"], .contentItem__teamBorder[style*="rgb(207,208,209)"],
  .ColorBorder[style*="#d9d9d9"], .contentItem__teamBorder[style*="#d9d9d9"],
  .ColorBorder[style*="#D9D9D9"], .contentItem__teamBorder[style*="#D9D9D9"],
  .ColorBorder[style*="rgb(217, 217, 217)"], .contentItem__teamBorder[style*="rgb(217, 217, 217)"],
  .ColorBorder[style*="rgb(217,217,217)"], .contentItem__teamBorder[style*="rgb(217,217,217)"],
  .ColorBorder[style*="#dcdddf"], .contentItem__teamBorder[style*="#dcdddf"],
  .ColorBorder[style*="#DCDDDF"], .contentItem__teamBorder[style*="#DCDDDF"],
  .ColorBorder[style*="rgb(220, 221, 223)"], .contentItem__teamBorder[style*="rgb(220, 221, 223)"],
  .ColorBorder[style*="rgb(220,221,223)"], .contentItem__teamBorder[style*="rgb(220,221,223)"],
  .ColorBorder[style*="#e4e5e6"], .contentItem__teamBorder[style*="#e4e5e6"],
  .ColorBorder[style*="#E4E5E6"], .contentItem__teamBorder[style*="#E4E5E6"],
  .ColorBorder[style*="rgb(228, 229, 230)"], .contentItem__teamBorder[style*="rgb(228, 229, 230)"],
  .ColorBorder[style*="rgb(228,229,230)"], .contentItem__teamBorder[style*="rgb(228,229,230)"],
  .ColorBorder[style*="#edeef0"], .contentItem__teamBorder[style*="#edeef0"],
  .ColorBorder[style*="#EDEEF0"], .contentItem__teamBorder[style*="#EDEEF0"],
  .ColorBorder[style*="rgb(237, 238, 240)"], .contentItem__teamBorder[style*="rgb(237, 238, 240)"],
  .ColorBorder[style*="rgb(237,238,240)"], .contentItem__teamBorder[style*="rgb(237,238,240)"],
  .ColorBorder[style*="#f1f2f3"], .contentItem__teamBorder[style*="#f1f2f3"],
  .ColorBorder[style*="#F1F2F3"], .contentItem__teamBorder[style*="#F1F2F3"],
  .ColorBorder[style*="rgb(241, 242, 243)"], .contentItem__teamBorder[style*="rgb(241, 242, 243)"],
  .ColorBorder[style*="rgb(241,242,243)"], .contentItem__teamBorder[style*="rgb(241,242,243)"],
  .ColorBorder[style*="#f5f5f5"], .contentItem__teamBorder[style*="#f5f5f5"],
  .ColorBorder[style*="#F5F5F5"], .contentItem__teamBorder[style*="#F5F5F5"],
  .ColorBorder[style*="rgb(245, 245, 245)"], .contentItem__teamBorder[style*="rgb(245, 245, 245)"],
  .ColorBorder[style*="rgb(245,245,245)"], .contentItem__teamBorder[style*="rgb(245,245,245)"],
  .ColorBorder[style*="#ffffff"], .contentItem__teamBorder[style*="#ffffff"],
  .ColorBorder[style*="#FFFFFF"], .contentItem__teamBorder[style*="#FFFFFF"],
  .ColorBorder[style*="rgb(255, 255, 255)"], .contentItem__teamBorder[style*="rgb(255, 255, 255)"],
  .ColorBorder[style*="rgb(255,255,255)"], .contentItem__teamBorder[style*="rgb(255,255,255)"] {
    background-color: #2d333b !important; }

  /* ---- Gamecast Matchup Predictor: the win-probability percentages and their "%"
       suffix hardcode near-black #101113 (fine on the site's white card) → ~1.4:1
       once the card is dark. The team abbreviations beside them are already light. */
  .matchupPredictor__teamValue, .matchupPredictor__teamValue div,
  .matchupPredictor__suffix { color: #e6edf3 !important; -webkit-text-fill-color: #e6edf3 !important; }

  /* ---- Player headshot discs ship a solid white circle behind a transparent PNG.
       This was already fixed inside .Gamecast__Baseball, but every sibling using the
       same component (gamecast WIN/LOSS/SAVE pitchers, athlete rows) kept the glare.
       .headshot-md is the one-feed shortstop-card variant and .author-img the story
       byline mugshot — same white disc, different class, and at 40px both duck the
       audit's size floor. */
  .headshot, .headshot-md, .author-img { background-color: #1c2128 !important; }
  /* The disc's outline is an inset #dcdddf box-shadow, not a border, so the blanket border
     reset leaves a bright ring around every avatar. */
  .headshot, .headshot-sm, .headshot-md, .author-img {
    box-shadow: 0 0 0 1px #2d333b inset !important; }

  /* News-item fallback thumbnail (.News__Item__Thumbnail.no-img): when a headline has no
     image ESPN paints a light #edeef0 rounded box holding a faint grey ESPN wordmark. On
     the dark news rails (player/team pages, news feeds) it glares as a light square. Dark
     it to the card surface. Audit-blind: the 60px box slips the big() size floor. */
  .News__Item__Thumbnail.no-img, .News__Item__Thumbnail--no-img,
  .Thumbnail.no-img { background-color: #1c2128 !important; }

  /* ---- espnfitt maps its .bg-clr-gray-NN SURFACE utilities onto the same
       --color-neutral-* tokens we remap for TEXT. Result: gray-01/02 (ESPN's darkest
       surfaces, #151617 / #2b2c2d) resolved to our light text greys — the mobile-nav
       icon rail and the sticky .Site__Header shipped as #c4cdd6 panels. Pin the
       surface utilities directly so they no longer ride the text tokens. ---- */
  .bg-clr-gray-01, .bg-clr-gray-02 { background-color: #0d1117 !important; }
  .bg-clr-gray-03, .bg-clr-gray-04, .bg-clr-gray-05 { background-color: #21262d !important; }
  .bg-clr-gray-06, .bg-clr-gray-07, .bg-clr-gray-08,
  .bg-clr-gray-09, .bg-clr-gray-10 { background-color: #1c2128 !important; }
  /* Mobile hamburger flyout (#global-nav-mobile): the dark left icon rail is ul.tier-1
     (rides the bg-clr-gray utilities above), but the sport-list panel that slides out
     — ul.tier-2 (and the nested ul.tier-3 league list) — ships a solid WHITE panel.
     Closed at load + only on a narrow viewport = audit-blind twice over. Dark the tier
     panels + their rows; the sport links are already our readable blue. ---- */
  #global-nav-mobile ul.tier-2, #global-nav-mobile ul.tier-3,
  #global-nav-mobile ul.tier-2 li, #global-nav-mobile ul.tier-3 li {
    background-color: #14181d !important; border-color: #262c33 !important; }
  #global-nav-mobile ul.tier-2 a:hover, #global-nav-mobile ul.tier-3 a:hover {
    background-color: #1c2128 !important; }
  /* Mobile-nav search reveal (.global-search) collapses to 0×0 at load and expands to a
     solid #edeef0 white panel when the in-menu search is tapped — closed-state white the
     load-time scan can't see. Scope to the mobile nav so the transparent desktop
     .global-search is untouched. ---- */
  #global-nav-mobile .global-search { background-color: #14181d !important; }
  /* Mobile scoreboard date carousel (.DatePicker--5DayMobile) month-picker button:
     .DateCarousel__MonthTrigger ships a solid white (rgba(255,255,255,.8)) 50×50 box
     with a dark calendar glyph (fill #151617) → a glaring white square with a dark-on-white
     icon on the dark carousel. espnfitt-only, so a desktop-viewport scan misses it. Dark
     the box, lighten the glyph. ---- */
  .DateCarousel__MonthTrigger {
    background-color: #1c2128 !important; border-color: #2d333b !important; }
  .DateCarousel__MonthTrigger svg, .DateCarousel__MonthTrigger path,
  .DateCarousel__MonthTrigger use { fill: #c4cdd6 !important; }
  /* The month-picker popover the trigger above opens (every scoreboard/fixtures page,
     desktop AND mobile): .DatePicker__MonthContainer is a 375×415 solid-white card with
     a near-white #edeef0 halo box-shadow. Closed at load, so no load-time scan sees it.
     Its "August 2026" caption is a hardcoded near-black (#151617) that survives our
     token remaps, and ESPN separates the SELECTED day from the rest by tone (#000 bold
     vs #48494a) — our broad text rule paints both the same grey, leaving weight as the
     only cue. Dark the card, lift the caption, restore the selected day's brighter ink. */
  .DatePicker__MonthContainer, .DatePicker__MonthContainer.calendar--embedded {
    background-color: #1c2128 !important; border-color: #2d333b !important;
    box-shadow: 0 0 3px 3px #14181d !important; }
  .MonthContainer__MonthYear { color: #e6edf3 !important; }
  .MonthContainer__Day--selected {
    color: #ffffff !important; -webkit-text-fill-color: #ffffff !important; }
  /* The popover's own chrome is drawn by two pseudo-elements the `*` border reset cannot
     reach: ::before is the CSS-triangle pointer (border-bottom #fff) and ::after is the
     rotated #edeef0 rule under the caption. Both were invisible while the card was white
     and glare once it darks. The trigger's ::before is the same story — a 1px #edeef0
     divider beside the calendar icon. */
  .MonthContainer__Header::before { border-bottom-color: #1c2128 !important; }
  .MonthContainer__Header::after { border-color: #2d333b !important; }
  .DateCarousel__MonthTrigger::before {
    background-color: #2d333b !important; border-color: #2d333b !important; }
  /* Mobile favourites/sport-shortcut strip (ul.fav-menu.strip.mobile, "favorites_mgmt"):
     the espnfitt mobile frontend paints a solid WHITE 390×64 nav band right below the
     header carrying the sport shortcut icons + blue labels → a glaring white strip on the
     dark mobile home. Only the mobile variant exists (`.fav-menu.strip` is mobile-only),
     the icons are transparent-PNG league logos + blue icon-font glyphs (survive on dark).
     Only visible on the mobile frontend (needs a mobile UA), so a desktop-viewport scan
     misses it. Dark to the page base. ---- */
  ul.fav-menu.strip, .fav-menu.strip.mobile { background-color: #14181d !important; }
  ul.fav-menu.strip li:hover, .fav-menu.strip.mobile li:hover { background-color: #1c2128 !important; }
  /* Mobile one-feed score-card odds strip: .oddsStripWrapper hardcodes #fff and the
     .oddsStrip row inside it #f4f4f4 (ESPN ships a [data-appearance='dark'] half at
     #1d1e1f/#2b2c2d that never applies for us), and the accordion caret is a pure-black
     ESPNIcons pseudo. The betting rows are natively transparent — the theme's
     [class*="betting"] surface rule fills them, which reads as an inset box once the
     strip itself is dark, so clear them in this scope. The strip only mounts on cards
     whose market has odds enabled; a disabled card renders it at 0px. ---- */
  .oddsStripContent .oddsStripWrapper { background-color: #1c2128 !important; }
  .oddsStripContent .oddsStrip { background-color: #21262d !important; }
  .oddsStrip .bettingWrapper, .oddsStrip .betting, .oddsStrip .bettingLabel,
  .oddsStrip .bettingPrimary, .oddsStrip .bettingSecondary,
  .oddsStrip .bettingTeamSeparator { background-color: transparent !important; }
  .oddsStripCaret, .oddsStripCaret::before { color: #c4cdd6 !important; }

  /* ---- Taboola "why this ad" fade / popover panels are solid white and only exist
       once the widget's exclude control is used — invisible to a load-time scan. ---- */
  .trc_exclude_overlay, .trc_popover, .trc_popover_title_wrapper {
    background-color: #1c2128 !important; }

  /* ---- Carousel navigation arrows: the legacy slick arrows (homepage miniCard
       carousel) AND the next-gen prism .CarouselArrow (gamecast Video-Highlights
       carousel) each ship a translucent WHITE disc (rgba(255,255,255,.8)) that glares
       against the dark card / thumbnail. Both are floating buttons that overlay content,
       so a load-time bg scan sees them but reads them as an intended affordance — like
       the scores-prev/next arrows the theme already darks. The slick glyph is an
       ESPNIcons char painted link-blue #0066cc (~2:1 once the disc is dark); the
       CarouselArrow glyph is already white. Dark the disc, lighten the slick glyph. ---- */
  .slick-prev, .slick-next, .CarouselArrow, button.CarouselArrow {
    background-color: rgba(20,24,29,0.7) !important; border-color: #2d333b !important; }
  .slick-prev::before, .slick-next::before { color: #e6edf3 !important; }
  /* Unlike the borderless slick arrows, .CarouselArrow draws a 2px brand-blue ring that
     matches its chevron; the shared reset above greys it into the thumbnail. */
  .CarouselArrow, button.CarouselArrow { border-color: #4c99e6 !important; }

  /* ---- Video-playlist "Now Playing" marker (.MediaList__item__playing): ESPN paints
       this label native red #dd0000 to flag the currently-playing clip in a video rail;
       our generic li/span text rule flattened it to grey so it read as ordinary
       metadata. Restore the red state signal (matching the theme's clr-negative /
       cscore--live live-red treatment). .mediaList__phase is the LEGACY homepage
       "Top Videos" rail's equivalent marker (span "Now Playing" inside an anchor, so
       our a span blue rule — not the grey one — flattened it); same native #dd0000. */
  .MediaList__item__playing, .mediaList__phase {
    color: #ff5a5a !important; -webkit-text-fill-color: #ff5a5a !important; }

  /* ---- Soccer red-card icon (scoreboard goal lists, match pages). ESPN authors it as
       `fill: var(--icon-default, var(--color-red-600, #d00))` — it only renders red
       because --icon-default is undefined on the light site. Our fusion token block
       defines --icon-default (needed for every other glyph), so the card resolves to our
       neutral grey and a RED card renders identical to a plain white/neutral one, right
       next to the grey goal icons. Pin the fill back to a readable-on-dark red. ---- */
  .SoccerPerformers__RedCardIcon { fill: #ff5a5a !important; }

  /* ---- Match-stats comparison bars (prism ProgressBar, gamecast "Team Stats"): the
       first team's segment carries its fill INLINE and the second's is a diagonal hatch.
       Two inline values land invisible (~1.0:1) on our dark card: ESPN's own near-black
       neutral #1d1e1f, and pure #000000 for a genuinely black-kitted club (Juventus).
       A 44%-vs-56% split then renders as one bar, and the 12px legend swatch beside the
       team abbreviation disappears with it. Both nodes carry only hashed classes, so the
       inline value is the only stable hook; the swatch is a <span>, the bar the testid. ---- */
  [data-test-id="prism-progress-bar"][style*="rgb(29, 30, 31)"],
  [data-test-id="prism-progress-bar"][style*="#1d1e1f"],
  [data-test-id="prism-progress-bar"][style*="rgb(0, 0, 0)"],
  [data-test-id="prism-progress-bar"][style*="#000000"],
  span[style*="background:#1d1e1f"],
  span[style*="background:#000000"] { background-color: #c4cdd6 !important; }

  /* ---- Form-guide result badges (.GameResults — "Last Five Matches" table + the
       head-to-head "Last 5 Matchups" panel on a match report): ESPN paints each W/L/D
       its outcome colour — win green (#108915), loss red (#b80000), draw grey (#444) —
       as a form signal. The badge is a span inside an .AnchorLink, so our a / a span blue
       rule flattened all three to identical link-blue, erasing the signal (a win read the
       same as a loss). The span carries BOTH .GameResults and its --win/--loss modifier,
       so a two-class selector clears the `a span` specificity tie. Restore readable-on-dark
       win-green / loss-red, draw a muted grey. ---- */
  span.GameResults { color: #9aa4ae !important; -webkit-text-fill-color: #9aa4ae !important; }
  .GameResults.GameResults--win {
    color: #4ac76a !important; -webkit-text-fill-color: #4ac76a !important; }
  .GameResults.GameResults--loss {
